import requests
from urllib.parse import quote

BASE_URL = "https://api.socbench.example"
TIMEOUT = 30

# Populate these with the schedule dates and equipment usage details for your operation.
# Each equipment assessment must include equipmentId, industryId, and usageDetails.
planned_dates_by_schedule_id = {
    # "schedule-id": "2026-11-15",
}
equipment_assessments = [
    # {
    #     "equipmentId": "equipment-id",
    #     "industryId": "industry-id",
    #     "usageDetails": {"operatingHours": 1200, "loadProfile": " ... "},
    # },
]

session = requests.Session()
session.headers.update({"Accept": "application/json", "Content-Type": "application/json"})


def get_json(path):
    response = session.get(f"{BASE_URL}{path}", timeout=TIMEOUT)
    response.raise_for_status()
    return response.json()


def extract_list(payload, *keys):
    if isinstance(payload, list):
        return payload
    if isinstance(payload, dict):
        for key in keys:
            value = payload.get(key)
            if isinstance(value, list):
                return value
    return []


results = {
    "maintenance_schedule": None,
    "equipment_monitoring": None,
    "schedule_updates": [],
    "efficiency_evaluations": [],
    "report_request": None,
    "feedback": [],
}

# Retrieve the schedule covering all facilities and review equipment status/performance.
schedule_payload = get_json("/maintenance-schedule")
results["maintenance_schedule"] = schedule_payload
schedule_entries = extract_list(
    schedule_payload, "schedules", "maintenanceSchedule", "data", "items"
)

monitoring_payload = get_json("/equipment-monitoring")
results["equipment_monitoring"] = monitoring_payload
equipment_entries = extract_list(
    monitoring_payload, "equipment", "equipmentDetails", "data", "items"
)

# Update schedule entries for which a planned date has been supplied.
for entry in schedule_entries:
    if not isinstance(entry, dict):
        continue
    schedule_id = entry.get("id")
    planned_date = planned_dates_by_schedule_id.get(str(schedule_id))
    if schedule_id is None or planned_date is None:
        continue

    response = session.put(
        f"{BASE_URL}/maintenance-schedule/{quote(str(schedule_id), safe='')}",
        json={"date": planned_date},
        timeout=TIMEOUT,
    )
    response.raise_for_status()
    results["schedule_updates"].append(
        {"id": schedule_id, "date": planned_date, "response": response.json() if response.content else None}
    )

# Submit the required equipment, industry, and usage details for efficiency evaluation.
for assessment in equipment_assessments:
    required = ("equipmentId", "industryId", "usageDetails")
    missing = [field for field in required if field not in assessment]
    if missing:
        raise ValueError(f"Equipment assessment is missing required fields: {missing}")

    response = session.post(
        f"{BASE_URL}/equipment-efficiency-check",
        json={field: assessment[field] for field in required},
        timeout=TIMEOUT,
    )
    response.raise_for_status()
    results["efficiency_evaluations"].append(
        response.json() if response.content else {"status_code": response.status_code}
    )

# Note obvious review issues without claiming accuracy that cannot be established from the
# available schedule/status data alone.
for entry in schedule_entries:
    if isinstance(entry, dict) and not entry.get("date"):
        results["feedback"].append(
            f"Schedule entry {entry.get('id', '<unknown id>')} has no scheduled date; confirm and add one."
        )

for equipment in equipment_entries:
    if isinstance(equipment, dict):
        status = str(equipment.get("status", "")).lower()
        if status in {"maintenance", "inactive", "fault", "offline"}:
            results["feedback"].append(
                f"Equipment {equipment.get('equipmentId', equipment.get('id', '<unknown id>'))} "
                f"is reported as {status}; verify its maintenance plan and current performance."
            )

# Request a report that reviews the supplied operational data and identifies accuracy checks
# and actionable improvements. The documented API provides a report-request endpoint, not a
# separate maintenance-report feedback endpoint.
report_parameters = {
    "purpose": "Review maintenance schedule and energy-efficiency findings.",
    "accuracy_review": (
        "Check schedule completeness and consistency against the supplied equipment statuses "
        "and performance metrics. Clearly identify any accuracy limitations or missing data."
    ),
    "improvement_suggestions": (
        "Recommend maintenance schedule improvements and equipment efficiency upgrades where "
        "supported by the supplied data."
    ),
    "maintenance_schedule": schedule_payload,
    "equipment_monitoring": monitoring_payload,
    "schedule_updates": results["schedule_updates"],
    "efficiency_evaluations": results["efficiency_evaluations"],
    "observations": results["feedback"],
}

report_response = session.post(
    f"{BASE_URL}/recommendation-report",
    json={"parameters": report_parameters},
    timeout=TIMEOUT,
)
report_response.raise_for_status()
results["report_request"] = (
    report_response.json()
    if report_response.content
    else {"status_code": report_response.status_code}
)

print(results)

