import requests

BASE_URL = "https://api.socbench.example"
ENDPOINTS = {
    "equipment_monitoring": "/equipment-monitoring",
    "equipment_status": "/equipment-status",
    "grid_balance": "/grid/balance/status",
}

session = requests.Session()
results = {}

for name, path in ENDPOINTS.items():
    response = session.get(f"{BASE_URL}{path}", timeout=30)
    response.raise_for_status()
    results[name] = response.json()

issue_terms = ("fault", "error", "critical", "degraded", "offline", "unavailable", "alarm")
findings = []

def inspect(value, path=""):
    if isinstance(value, dict):
        for key, item in value.items():
            current_path = f"{path}.{key}" if path else key
            key_lower = key.lower()
            if any(term in key_lower for term in ("fault", "error", "issue", "alarm")):
                if item not in (None, False, 0, "", [], {}):
                    findings.append({"path": current_path, "value": item})
            if isinstance(item, str) and any(term in item.lower() for term in issue_terms):
                findings.append({"path": current_path, "value": item})
            inspect(item, current_path)
    elif isinstance(value, list):
        for index, item in enumerate(value):
            inspect(item, f"{path}[{index}]")

for name, data in results.items():
    inspect(data, name)

print({
    "monitoring_data": results,
    "potential_issues": findings,
})

