import requests

BASE_URL = "https://api.socbench.example"
TIMEOUT = 30


def response_data(response):
    response.raise_for_status()
    try:
        return response.json()
    except ValueError:
        return {}


def records_from(data, keys):
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        for key in keys:
            value = data.get(key)
            if isinstance(value, list):
                return value
    return []


# Add the mining site.
site_response = requests.post(
    f"{BASE_URL}/sites/add",
    json={
        "name": "Site X",
        "location": "45.4215° N, 75.6972° W",
    },
    timeout=TIMEOUT,
)
site_data = response_data(site_response)
site_id = site_data.get("siteId") or site_data.get("id") or "1"

# Get the machinery's current operational status and schedule maintenance
# for equipment identified as operational.
equipment_status = response_data(
    requests.get(f"{BASE_URL}/equipment-status", timeout=TIMEOUT)
)
equipment = records_from(
    equipment_status,
    ("equipment", "items", "data", "results"),
)


def is_operational(item):
    if not isinstance(item, dict):
        return False
    status = str(item.get("status", item.get("operationalStatus", ""))).lower()
    return status in {"operational", "operating", "active", "running"}


operational_equipment = [item for item in equipment if is_operational(item)]
equipment_ids = [
    item.get("id") or item.get("equipmentId")
    for item in operational_equipment
    if item.get("id") or item.get("equipmentId")
]

maintenance_response = requests.post(
    f"{BASE_URL}/equipment/maintenance-schedule",
    json={
        "siteId": site_id,
        "equipmentIds": equipment_ids,
    },
    timeout=TIMEOUT,
)
maintenance_response.raise_for_status()

# Retrieve site resources, project-related materials, and inventory status.
resources = response_data(
    requests.get(
        f"{BASE_URL}/sites/resources-overview",
        params={"siteId": site_id},
        timeout=TIMEOUT,
    )
)
materials = response_data(
    requests.get(
        f"{BASE_URL}/materials",
        params={"siteId": site_id},
        timeout=TIMEOUT,
    )
)
inventory = response_data(
    requests.get(
        f"{BASE_URL}/inventory/status",
        params={"siteId": site_id},
        timeout=TIMEOUT,
    )
)

inventory_items = records_from(
    inventory,
    ("inventory", "items", "materials", "data", "results"),
)
obsolete_materials = [
    item
    for item in inventory_items
    if isinstance(item, dict)
    and str(item.get("status", item.get("condition", ""))).lower()
    in {"obsolete", "expired", "discontinued"}
]

# The documented API has no endpoint for deleting inventory items or retrieving
# regulatory updates. Record those limitations rather than calling undocumented
# endpoints.
custom_report = {
    "site": site_data,
    "resources": resources,
    "materials": materials,
    "current_operational_status": equipment_status,
    "operational_equipment_scheduled_for_maintenance": equipment_ids,
    "obsolete_materials_identified": obsolete_materials,
    "obsolete_material_removal": (
        "Not performed: no inventory-removal endpoint is documented."
    ),
    "regulatory_updates": (
        "Unavailable: no regulatory-updates endpoint is documented."
    ),
}

print(custom_report)

