def material_name(material):
    if isinstance(material, dict):
        return material.get("name") or material.get("materialName") or material.get("material")
    return material if isinstance(material, str) else None

# Request recyclability-improvement recommendations for each material available
# in the returned inventory. If no inventory is exposed, use the available
# material categories as the best documented fallback.
