import requests

API_BASE = "https://api.socbench.example"
TIMEOUT = 30

# Populate these with the categories and material quantities required for the review.
PRODUCT_CATEGORIES = []
REQUIRED_MATERIALS = [
    # {"material_id": "material-id", "quantity": 100}
]


def get_json(path):
    response = requests.get(f"{API_BASE}{path}", timeout=TIMEOUT)
    response.raise_for_status()
    return response.json()


def post_json(path, payload):
    response = requests.post(
        f"{API_BASE}{path}",
        json=payload,
        timeout=TIMEOUT,
    )
    response.raise_for_status()
    return response.json() if response.content else None


def category_name(category):
    if isinstance(category, dict):
        return str(category.get("name", category.get("category", "")))
    return str(category)


def identify_outdated_materials(inventory):
    outdated_statuses = {"outdated", "obsolete", "expired"}
    result = []

    if not isinstance(inventory, list):
        return result

    for item in inventory:
        if not isinstance(item, dict):
            continue

        status = str(item.get("status", "")).strip().lower()
        if item.get("outdated") is True or status in outdated_statuses:
            result.append(item)

    return result


def main():
    trends = get_json("/market-trends")
    categories = get_json("/materials/categories")
    inventory = get_json("/inventory/status")

    requested_categories = {name.lower() for name in PRODUCT_CATEGORIES}
    available_categories = categories if isinstance(categories, list) else []

    if requested_categories:
        matching_categories = [
            category
            for category in available_categories
            if category_name(category).lower() in requested_categories
        ]
    else:
        matching_categories = available_categories

    # Keep trend analysis focused on the requested categories when the response
    # contains text mentioning those categories.
    trend_text = str(trends)
    category_trends = {
        category_name(category): (
            trend_text
            if category_name(category).lower() in trend_text.lower()
            else None
        )
        for category in matching_categories
    }

    procurement = None
    if REQUIRED_MATERIALS:
        procurement = post_json(
            "/procurement/request",
            {"materials": REQUIRED_MATERIALS},
        )

    compliance_results = {}
    for material in REQUIRED_MATERIALS:
        material_id = material.get("material_id") if isinstance(material, dict) else None
        if material_id:
            compliance_results[str(material_id)] = get_json(
                f"/materials/{material_id}/compliance"
            )

    outdated_materials = identify_outdated_materials(inventory)

    # The documented API has no endpoint for deleting or removing inventory
    # materials, so outdated records are reported but cannot be removed here.
    return {
        "trends": trends,
        "category_trends": category_trends,
        "available_categories": categories,
        "matching_categories": matching_categories,
        "procurement": procurement,
        "compliance_results": compliance_results,
        "outdated_materials_identified": outdated_materials,
        "outdated_materials_removed": False,
    }


if __name__ == "__main__":
    result = main()
    print(result)

