import datetime
import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()


def request_json(method, path, **kwargs):
    response = session.request(method, f"{BASE_URL}{path}", timeout=30, **kwargs)
    response.raise_for_status()
    if not response.content:
        return {}
    return response.json()


def inventory_items(payload):
    if isinstance(payload, list):
        return payload
    if isinstance(payload, dict):
        for key in ("inventory", "items", "materials", "facilities"):
            value = payload.get(key)
            if isinstance(value, list):
                return value
    return []


def material_name(item):
    return item.get("materialName") or item.get("name")


def compliance_required(item, classification_result):
    for source in (item, classification_result):
        for key in ("requiresCompliance", "complianceRequired", "requires_compliance"):
            if key in source:
                return bool(source[key])
    return False


def is_compliant(result):
    value = result.get("compliant", result.get("isCompliant"))
    if value is not None:
        return bool(value)
    status = str(result.get("status", "")).lower()
    return status in {"compliant", "passed", "approved"}


inventory_response = request_json("GET", "/inventory/status")
items = inventory_items(inventory_response)

# Only classify materials currently shown as available in inventory.
available_items = []
for item in items:
    quantity = item.get("quantity")
    if quantity is None or quantity > 0:
        available_items.append(item)

results = []
for item in available_items:
    name = material_name(item)
    if not name:
        continue

    classification_result = request_json(
        "POST",
        "/materials/classify",
        json={"materialName": name},
    )

    compliance_result = None
    if compliance_required(item, classification_result) and item.get("id") is not None:
        compliance_result = request_json(
            "GET",
            f"/materials/{item['id']}/compliance",
        )

    classification = str(classification_result.get("classification", "")).lower()
    if compliance_result is not None and not is_compliant(compliance_result):
        shipment_route = "compliance_review"
    elif any(word in classification for word in ("recycl", "reusable")):
        shipment_route = "recycling"
    else:
        shipment_route = "non_recyclable_processing"

    # The materials update endpoint accepts key-value material properties;
    # use it to record the route when the inventory entry has a material ID.
    if item.get("id") is not None:
        request_json(
            "PUT",
            f"/materials/{item['id']}",
            json={"shipmentRoute": shipment_route},
        )

    results.append({
        "materialName": name,
        "classification": classification_result,
        "compliance": compliance_result,
        "shipmentRoute": shipment_route,
    })

start_date = (datetime.date.today() - datetime.timedelta(days=30)).isoformat()
statistics = request_json(
    "GET",
    "/analysis/statistics",
    params={"startDate": start_date},
)

# The documented API has no machinery-maintenance scheduling endpoint, and its
# statistics endpoint reports classified-material statistics rather than
# resource-usage statistics. Those actions cannot be submitted through the
# documented endpoints.
print({
    "inventory": inventory_response,
    "materialResults": results,
    "classificationStatistics": statistics,
})

