import os
import requests

BASE_URL = "https://api.socbench.example"
TIMEOUT = 30

# Replace these sample goods and quantities with the orders to create.
new_orders = [
    {"item_id": "industrial-good-1001", "quantity": 10},
    {"item_id": "industrial-good-1002", "quantity": 5},
]

# Optionally provide IDs explicitly through environment variables.
specific_order_id = os.getenv("ORDER_ID")
inventory_item_id = os.getenv("ITEM_ID", "industrial-good-1001")


def response_json(response):
    response.raise_for_status()
    if response.status_code == 204:
        return None
    return response.json()


def find_order_id(value):
    """Find an order ID in a create-order response."""
    if isinstance(value, dict):
        for key in ("order_id", "id"):
            if value.get(key) is not None:
                return value[key]
        for nested in value.values():
            found = find_order_id(nested)
            if found is not None:
                return found
    elif isinstance(value, list):
        for nested in value:
            found = find_order_id(nested)
            if found is not None:
                return found
    return None


def maintenance_records(data):
    """Extract recommendation or schedule records from common response shapes."""
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        for key in ("recommendations", "maintenance", "schedule", "data", "results"):
            value = data.get(key)
            if isinstance(value, list):
                return value
        return [data]
    return []


# Create multiple orders.
created_orders = response_json(
    requests.post(
        f"{BASE_URL}/orders",
        json=new_orders,
        timeout=TIMEOUT,
    )
)

# Retrieve the summary of all existing orders after creation.
orders_summary = response_json(
    requests.get(
        f"{BASE_URL}/orders",
        timeout=TIMEOUT,
    )
)

# Fetch a specific order using its ID, preferring the configured ID and
# otherwise using an ID returned when creating the orders.
if specific_order_id is None:
    specific_order_id = find_order_id(created_orders)

if specific_order_id is None:
    raise ValueError(
        "No order ID was provided or returned. Set the ORDER_ID environment variable."
    )

order_details = response_json(
    requests.get(
        f"{BASE_URL}/orders/{specific_order_id}",
        timeout=TIMEOUT,
    )
)

# Retrieve maintenance recommendations and build a local resource allocation plan.
maintenance_data = response_json(
    requests.get(
        f"{BASE_URL}/maintenance_schedule",
        timeout=TIMEOUT,
    )
)

priority_rank = {"critical": 0, "high": 1, "medium": 2, "low": 3}
recommendations = maintenance_records(maintenance_data)
recommendations.sort(
    key=lambda record: priority_rank.get(
        str(record.get("priority", record.get("severity", "medium"))).lower(),
        2,
    )
    if isinstance(record, dict)
    else 2
)

resource_allocation = []
for recommendation in recommendations:
    if not isinstance(recommendation, dict):
        continue

    priority = str(
        recommendation.get("priority", recommendation.get("severity", "medium"))
    ).lower()
    resource_allocation.append(
        {
            "recommendation_id": recommendation.get(
                "id", recommendation.get("recommendation_id")
            ),
            "machine_id": recommendation.get(
                "machine_id", recommendation.get("asset_id")
            ),
            "priority": priority,
            "recommended_action": recommendation.get(
                "recommendation",
                recommendation.get("action", recommendation.get("description")),
            ),
            "resources": recommendation.get(
                "required_resources", recommendation.get("resources", [])
