def collect_allergen_names(value, parent_key=""):
    if isinstance(value, dict):
        for key, item in value.items():
            key_normalized = re.sub(r"[^a-z]", "", key.lower())
            if key_normalized in {"allergen", "allergens", "allergenname"}:
                if isinstance(item, str):
                    allergen_names.add(item.strip())
                elif isinstance(item, list):
                    allergen_names.update(
                        entry.strip() for entry in item if isinstance(entry, str)
                    )
                elif isinstance(item, dict):
                    for name_key in ("name", "allergen", "label"):
                        name = item.get(name_key)
                        if isinstance(name, str):
                            allergen_names.add(name.strip())
            collect_allergen_names(item, key)
    elif isinstance(value, list):
        for item in value:
            collect_allergen_names(item, parent_key)

