import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()
session.headers.update({"Accept": "application/json", "Content-Type": "application/json"})


def request_json(method, path, **kwargs):
    response = session.request(method, f"{BASE_URL}{path}", timeout=30, **kwargs)
    response.raise_for_status()
    if not response.content:
        return None
    return response.json()


def records_from(data, *keys):
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        for key in keys:
            value = data.get(key)
            if isinstance(value, list):
                return value
    return []


# Retrieve inventory across all locations and aggregate quantities by item.
inventory_response = request_json("GET", "/inventory/status")
inventory_rows = records_from(inventory_response, "items", "inventory", "data")

stock_by_item = {}
for row in inventory_rows:
    if not isinstance(row, dict):
        continue
    item_id = row.get("itemId", row.get("id"))
    quantity = row.get("quantity")
    if item_id is None or not isinstance(quantity, (int, float)):
        continue
    stock_by_item[str(item_id)] = stock_by_item.get(str(item_id), 0) + quantity

# Submit the available inventory snapshot to generate demand predictions.
forecast_input = [
    {"itemId": item_id, "quantity": quantity}
    for item_id, quantity in stock_by_item.items()
]
forecast_response = request_json("POST", "/analytics/forecast", json=forecast_input)
forecast_rows = records_from(forecast_response, "predictions", "items", "data")

predicted_by_item = {}
for row in forecast_rows:
    if not isinstance(row, dict):
        continue
    item_id = row.get("itemId", row.get("id"))
    predicted_quantity = row.get("predictedQuantity")
    if item_id is not None and isinstance(predicted_quantity, (int, float)):
        predicted_by_item[str(item_id)] = predicted_quantity

# Order only the quantity needed to cover predicted demand beyond current stock.
items_to_order = [
    {"itemId": item_id, "quantity": predicted_quantity - stock_by_item.get(item_id, 0)}
    for item_id, predicted_quantity in predicted_by_item.items()
    if predicted_quantity > stock_by_item.get(item_id, 0)
]

order_response = None
if items_to_order:
    delivery_date = (date.today() + timedelta(days=7)).isoformat()
    order_response = request_json(
        "POST",
        "/orders/new",
        json={"items": items_to_order, "deliveryDate": delivery_date},
    )

# Retrieve supply-chain segment information and available performance metrics.
supply_chain_overview = request_json("GET", "/supplychain/overview")
performance_metrics = request_json("GET", "/performance/metrics")

# Review waste reports after preparing the restock order.
waste_reports = request_json("GET", "/waste/reports")

print(json.dumps({
    "inventory": inventory_response,
    "forecast": forecast_response,
    "itemsToOrder": items_to_order,
    "order": order_response,
    "supplyChainOverview": supply_chain_overview,
    "performanceMetrics": performance_metrics,
    "wasteReports": waste_reports,
}, indent=2))

