    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        for key in ("items", "results", "data", "equipment", "threats", "assets", "systems"):
            if isinstance(data.get(key), list):
                return data[key]
    return []

def searchable_text(record):
    if isinstance(record, dict):
        return " ".join(str(value) for value in record.values() if value is not None).lower()
    return str(record).lower()

stop_words = {
    "with", "from", "that", "this", "have", "into", "over", "under",
    "threat", "risk", "vulnerability", "equipment", "system", "asset",
    "detected", "logged", "current", "unknown",
}

