    response = client.post(
        f"{BASE_URL}/messages/reply",
        json={
            "messageId": message_id,
            "encryptedReply": encrypted_reply,
        },
    )
    response.raise_for_status()
    return response.json() if response.content else None


def perform_supported_actions(
    video_id,
    recipient_id,
    encrypted_message,
    message_id,
    encrypted_reply,
    session=None,
):
    return {
        "streaming_url": get_streaming_url(video_id, session),
        "sent_message": send_encrypted_message(
            recipient_id, encrypted_message, session
        ),
        "message_reply": reply_to_encrypted_message(
            message_id, encrypted_reply, session
        ),
        "unsupported_actions": UNSUPPORTED_ACTIONS,
    }

