import requests


BASE_URL = "https://api.socbench.example"


def analyze_period(start_date, end_date, region_id):
    with requests.Session() as session:
        sensor_response = session.get(
            f"{BASE_URL}/sensor-data",
            params={"start_date": start_date, "end_date": end_date},
            timeout=30,
        )
        sensor_response.raise_for_status()
        sensor_data = sensor_response.json()

        metrics_response = session.get(
            f"{BASE_URL}/efficiency/metrics",
            timeout=30,
        )
        metrics_response.raise_for_status()
        efficiency_metrics = metrics_response.json()

        detailed_analysis_response = session.post(
            f"{BASE_URL}/efficiency/metrics",
            json={
                "parameters": {
                    "start_date": start_date,
                    "end_date": end_date,
                    "region": region_id,
                }
            },
            timeout=30,
        )
        detailed_analysis_response.raise_for_status()
        detailed_efficiency_analysis = detailed_analysis_response.json()

        config_response = session.get(
            f"{BASE_URL}/regions/config",
            timeout=30,
        )
        config_response.raise_for_status()
        region_configurations = config_response.json()

        if isinstance(region_configurations, dict):
            configurations = region_configurations.get(
                "regions", region_configurations
            )
        else:
            configurations = region_configurations

        if isinstance(configurations, list):
            regional_configuration = next(
                (
                    configuration
                    for configuration in configurations
                    if configuration.get("region") == region_id
                    or configuration.get("region_id") == region_id
                    or configuration.get("id") == region_id
                ),
                None,
            )
        elif isinstance(configurations, dict):
            regional_configuration = configurations.get(region_id)
        else:
            regional_configuration = None

        forecast_response = session.post(
            f"{BASE_URL}/forecast",
            json={
                "region": region_id,
                "parameters": {
                    "start_date": start_date,
                    "end_date": end_date,
                },
            },
            timeout=30,
        )
        forecast_response.raise_for_status()
        custom_forecast = forecast_response.json()

    return {
        "period": {"start_date": start_date, "end_date": end_date},
        "region_id": region_id,
        "sensor_data": sensor_data,
        "efficiency_metrics": efficiency_metrics,
        "detailed_efficiency_analysis": detailed_efficiency_analysis,
        "region_configurations": region_configurations,
        "regional_configuration": regional_configuration,
        "custom_forecast": custom_forecast,
    }

