import requests

API_BASE = "https://api.socbench.example"
REGIONS = []  # Populate with the regions to analyze.
CRITICAL_REGIONS = []  # Populate with regions requiring high-priority recommendations.
BILLING_TEMPLATE_ID = None  # No documented endpoint supports billing-template configuration.


def find_numeric_value(data, keywords):
    """Find a numeric value whose key contains one of the supplied keywords."""
    if isinstance(data, dict):
        for key, value in data.items():
            if any(word in str(key).lower() for word in keywords):
                if isinstance(value, (int, float)) and not isinstance(value, bool):
                    return float(value)
        for value in data.values():
            result = find_numeric_value(value, keywords)
            if result is not None:
                return result
    elif isinstance(data, list):
        for value in data:
            result = find_numeric_value(value, keywords)
            if result is not None:
                return result
    return None


def main():
    session = requests.Session()
    session.headers.update({"Accept": "application/json"})

    demand_response = session.get(
        f"{API_BASE}/realtime-demand",
        timeout=30,
    )
    demand_response.raise_for_status()
    demand_data = demand_response.json()

    zone_response = session.get(
        f"{API_BASE}/zones-status",
        timeout=30,
    )
    zone_response.raise_for_status()
    zones_data = zone_response.json()

    forecasts = {}
    for region in REGIONS:
        response = session.get(
            f"{API_BASE}/forecast-patterns",
            params={"region": region},
            timeout=30,
        )
        response.raise_for_status()
        forecasts[region] = response.json()

    recommendations = []
    region_analysis = {}

    for region in REGIONS:
        forecast = forecasts.get(region)
        current_demand = find_numeric_value(
            demand_data, ("demand", "load", "usage", "power")
        )
        forecast_demand = find_numeric_value(
            forecast, ("demand", "load", "usage", "power", "forecast")
        )

        region_analysis[region] = {
            "current_demand": current_demand,
            "forecast": forecast,
            "forecast_demand": forecast_demand,
        }

        if region in CRITICAL_REGIONS:
            if (
                current_demand is not None
                and forecast_demand is not None
                and current_demand > forecast_demand
            ):
                recommendation = (
                    f"{region}: prioritize available capacity for this region, "
                    "defer non-essential loads, and investigate the demand "
                    "increase against the forecast."
                )
            else:
                recommendation = (
                    f"{region}: review peak-load scheduling, encourage "
                    "off-peak usage, and inspect local demand and forecast "
                    "conditions before reallocating capacity."
                )
            recommendations.append(
                {"region": region, "priority": "high", "recommendation": recommendation}
            )

    distribution_update = {
        "regions": REGIONS,
        "strategy": "adjust_based_on_realtime_demand_and_regional_forecasts",
        "demand_data": demand_data,
        "forecasts": forecasts,
    }
    update_response = session.put(
        f"{API_BASE}/adjust-distribution",
        json=distribution_update,
        timeout=30,
    )
    update_response.raise_for_status()

    inactive_zones = []

    def find_inactive(value, path=""):
        if isinstance(value, dict):
            status = str(value.get("status", "")).lower()
            active = value.get("active")
            if status in {"inactive", "offline", "decommissioned"} or active is False:
                inactive_zones.append({"path": path, "zone": value})
            for key, child in value.items():
                find_inactive(child, f"{path}/{key}")
        elif isinstance(value, list):
            for index, child in enumerate(value):
                find_inactive(child, f"{path}/{index}")

    find_inactive(zones_data)

    # The documented API has no billing-template configuration endpoint,
    # recommendation-notification endpoint, or distribution-point removal endpoint.
    result = {
        "demand_data": demand_data,
        "zone_status": zones_data,
        "region_analysis": region_analysis,
        "distribution_update_status": update_response.status_code,
        "recommendations": recommendations,
        "inactive_zones_identified_but_not_removed": inactive_zones,
        "unsupported_actions": {
            "review_billing_template": BILLING_TEMPLATE_ID,
            "notify_repair_teams": recommendations,
            "remove_inactive_distribution_points": inactive_zones,
        },
    }
    print(result)


if __name__ == "__main__":
    main()

