def get_json(path):
    response = requests.get(f"{BASE_URL}{path}", timeout=TIMEOUT)
    response.raise_for_status()
    return response.json()


def records_from(data):
    if isinstance(data, list):
        return [item for item in data if isinstance(item, dict)]
    if isinstance(data, dict):
        for key in ("data", "zones", "results", "reports", "forecasts"):
            value = data.get(key)
            if isinstance(value, list):
                return [item for item in value if isinstance(item, dict)]
        return [data]
    return []


def zone_id(record):
    for key in ("zone_id", "zoneId", "id"):
        if record.get(key) is not None:
            return str(record[key])
    return None


def demand_value(record):
    for key in ("demand", "electricity_demand", "current_demand", "load", "consumption"):
        try:
            value = float(record[key])
            if value >= 0:
                return value
        except (KeyError, TypeError, ValueError):
            continue
    return None


demand_data = get_json("/realtime-demand")
forecast_data = get_json("/forecast-patterns")
efficiency_data = get_json("/efficiency-reports")
renewables_data = get_json("/renewables-status")
zones_data = get_json("/zones-status")

demand_records = records_from(demand_data)
forecast_records = records_from(forecast_data)
zone_records = records_from(zones_data)
efficiency_records = records_from(efficiency_data)

forecast_by_zone = {}
for record in forecast_records:
    identifier = zone_id(record)
    value = demand_value(record)
    if identifier and value is not None:
        forecast_by_zone[identifier] = value

observed = [
    (zone_id(record), demand_value(record), record)
    for record in demand_records
    if zone_id(record) and demand_value(record) is not None
]

values = [value for _, value, _ in observed]
surge_zones = set()

for identifier, value, _ in observed:
    forecast = forecast_by_zone.get(identifier)
    if forecast is not None:
        if value > forecast:
            surge_zones.add(identifier)

if values:
    high_demand_cutoff = median(values)
    surge_zones.update(
        identifier for identifier, value, _ in observed
        if value >= high_demand_cutoff
    )

all_zone_ids = {
    identifier
    for record in demand_records + zone_records
    if (identifier := zone_id(record))
}

# Request high-priority resource allocation for zones with elevated demand.
allocation_results = []
for identifier in sorted(surge_zones):
    response = requests.post(
        f"{BASE_URL}/allocate-resources",
