three_properties = miami_properties[:3]
if len(three_properties) == 3:
    property_ids = [
        str(item.get("property_id", item.get("id")))
        for item in three_properties
    ]
    comparison_response = session.get(
        f"{BASE_URL}/properties/comparison",
        params={"property_ids": ",".join(property_ids)},
    )
    comparison_response.raise_for_status()
    print("Property comparison:")
    print(comparison_response.json())
else:
    print(f"Found only {len(three_properties)} Miami properties; three are needed for comparison.")

# Identify luxury-specialist agents from agent information included with Miami listings.
luxury_agents = {}
for prop in miami_properties:
    agent = prop.get("agent")
    if isinstance(agent, dict):
        name = agent.get("name") or agent.get("agent_name")
        specialties = agent.get("specialties") or agent.get("specialty") or []
        if isinstance(specialties, str):
            specialties = [specialties]
        if name and any("luxury" in str(item).lower() for item in specialties):
            luxury_agents[name] = agent
    elif isinstance(agent, str):
        specialties = prop.get("agent_specialties", prop.get("specialties", []))
        if isinstance(specialties, str):
            specialties = [specialties]
        if any("luxury" in str(item).lower() for item in specialties):
            luxury_agents[agent] = {"name": agent, "specialties": specialties}

print("Agents specializing in luxury homes in Miami:")
print(list(luxury_agents.values()))

